/**
 * The typed API client. Types come from the OpenAPI contract
 * (src/api/schema.d.ts, generated by `npm run api:types`), so a contract change
 * that breaks the web fails type checking.
 */
import createClient, {type Middleware} from 'openapi-fetch';

import type {components, paths} from './schema';

export type Schemas = components['schemas'];
export type ArtistSummary = Schemas['ArtistSummary'];
export type Evidence = Schemas['Evidence'];

/** An API failure, from the AIP-193 error envelope. */
export class ApiError extends Error {
  constructor(
    readonly httpStatus: number,
    readonly status: string,
    readonly reason: string,
    message: string,
    readonly metadata: Record<string, string> = {},
    readonly retryAfterSeconds: number | null = null,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

let csrfToken: string | null = null;

/** Set by the auth layer after sign-in or session restore; cleared on sign-out. */
export function setCsrfToken(token: string | null): void {
  csrfToken = token;
}

const WRITE_METHODS = new Set(['POST', 'PATCH', 'PUT', 'DELETE']);

const csrf: Middleware = {
  onRequest({request}) {
    if (csrfToken && WRITE_METHODS.has(request.method)) {
      request.headers.set('X-CSRF-Token', csrfToken);
    }
    return request;
  },
};

export const api = createClient<paths>({
  // Absolute, so Request() works outside a page too (tests, workers).
  baseUrl: globalThis.location?.origin ?? '',
  credentials: 'same-origin',
  // Resolve fetch per call, not at import, so it can be instrumented or stubbed later.
  fetch: request => globalThis.fetch(request),
});
api.use(csrf);

interface ErrorEnvelope {
  error?: {
    code?: number;
    status?: string;
    message?: string;
    details?: {reason?: string; metadata?: Record<string, string>}[];
  };
}

/** Converts an error body into an ApiError (network failures become UNAVAILABLE). */
export function toApiError(
  response: Response | undefined,
  body: unknown,
): ApiError {
  if (!response) {
    return new ApiError(0, 'UNAVAILABLE', 'NETWORK', 'Network error');
  }
  const envelope = (body ?? {}) as ErrorEnvelope;
  const detail = envelope.error?.details?.[0];
  const retryAfter = Number(response.headers.get('Retry-After'));
  return new ApiError(
    response.status,
    envelope.error?.status ?? 'UNKNOWN',
    detail?.reason ?? 'UNKNOWN',
    envelope.error?.message ?? response.statusText,
    detail?.metadata ?? {},
    Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : null,
  );
}

/** Unwraps an openapi-fetch result, throwing ApiError on failure. */
export async function unwrap<T>(
  call: Promise<{data?: T; error?: unknown; response: Response}>,
): Promise<T> {
  let result: {data?: T; error?: unknown; response: Response};
  try {
    result = await call;
  } catch {
    throw toApiError(undefined, undefined);
  }
  if (result.error !== undefined || result.data === undefined) {
    throw toApiError(result.response, result.error);
  }
  return result.data;
}

/** Returns the ID part of a resource name ("artists/abc" -> "abc"). */
export function idOf(name: string): string {
  return name.slice(name.indexOf('/') + 1);
}
